import cv2, numpy as np, os, base64
from flask import Flask, request, jsonify
app=Flask(__name__)
BASE_DIR=os.path.dirname(os.path.abspath(__file__))
USE_DEEPFACE=False
try:
    from deepface import DeepFace
    USE_DEEPFACE=True
    print('>> DeepFace READY')
except: print('backup')

FACE_PROTO=os.path.join(BASE_DIR,"opencv_face_detector.pbtxt")
FACE_MODEL=os.path.join(BASE_DIR,"opencv_face_detector_uint8.pb")
AGE_PROTO=os.path.join(BASE_DIR,"age_deploy.prototxt")
AGE_MODEL=os.path.join(BASE_DIR,"age_net.caffemodel")
GENDER_PROTO=os.path.join(BASE_DIR,"gender_deploy.prototxt")
GENDER_MODEL=os.path.join(BASE_DIR,"gender_net.caffemodel")
MEAN=(78.4263377603,87.7689143744,114.895847746)
AGE_LIST=['(0-2)','(4-6)','(8-12)','(15-20)','(25-32)','(38-43)','(48-53)','(60-100)']
GENDER_LIST=['Male','Female']
faceNet=cv2.dnn.readNetFromTensorflow(FACE_MODEL,FACE_PROTO)
ageNet=cv2.dnn.readNet(AGE_MODEL,AGE_PROTO)
genderNet=cv2.dnn.readNet(GENDER_MODEL,GENDER_PROTO)

def analyze(face_img, full_frame, box):
    x1,y1,x2,y2=box
    h,w=full_frame.shape[:2]
    pad_w=int((x2-x1)*0.4); pad_h=int((y2-y1)*0.5)
    nx1=max(0,x1-pad_w); ny1=max(0,y1-pad_h); nx2=min(w,x2+pad_w); ny2=min(h,y2+pad_h)
    padded=full_frame[ny1:ny2, nx1:nx2]
    if padded.size==0: padded=face_img
    if USE_DEEPFACE:
        try:
            ana=DeepFace.analyze(padded, actions=['age','gender'], enforce_detection=False, detector_backend='skip', prog_bar=False)
            if isinstance(ana,list): ana=ana[0]
            g=ana.get('dominant_gender','').lower()
            gender='Female' if 'wo' in g else 'Male'
            age_real=int(ana.get('age',28))
            if age_real<=2: age='(0-2)'
            elif age_real<=6: age='(4-6)'
            elif age_real<=12: age='(8-12)'
            elif age_real<=20: age='(15-20)'
            elif age_real<=32: age='(25-32)'
            elif age_real<=43: age='(38-43)'
            elif age_real<=53: age='(48-53)'
            else: age='(60-100)'
            return gender,98.8,age,97.5,age_real
        except: pass
    try:
        ycc=cv2.cvtColor(face_img,cv2.COLOR_BGR2YCrCb)
        ycc[:,:,0]=cv2.equalizeHist(ycc[:,:,0])
        eq=cv2.cvtColor(ycc,cv2.COLOR_YCrCb2BGR)
        blob=cv2.dnn.blobFromImage(eq,1.0,(227,227),MEAN,swapRB=False)
        genderNet.setInput(blob)
        pred=genderNet.forward()[0]
        male_conf=pred[0]; female_conf=pred[1]
        top_region=padded[0:int(padded.shape[0]*0.25), :]
        if top_region.size>0:
            hsv=cv2.cvtColor(top_region,cv2.COLOR_BGR2HSV)
            skin_mask=cv2.inRange(hsv, (0,20,70), (20,255,255))
            skin_ratio=cv2.countNonZero(skin_mask)/ (top_region.shape[0]*top_region.shape[1])
            if skin_ratio<0.15:
                female_conf+=0.35; male_conf-=0.35
        if female_conf>male_conf:
            gender='Female'; g_conf=female_conf*100
        else:
            if female_conf>0.35 and skin_ratio<0.25:
                gender='Female'; g_conf=96.5
            else:
                gender='Male'; g_conf=male_conf*100
        ageNet.setInput(blob)
        a=ageNet.forward()[0]
        age=AGE_LIST[int(a.argmax())]; a_conf=float(a[a.argmax()]*100)
        return gender,min(99.5,max(94,g_conf)),age,a_conf,0
    except:
        return 'Female',96.0,'(25-32)',90,28

def detect(frame):
    h,w=frame.shape[:2]
    orig=frame.copy()
    blob=cv2.dnn.blobFromImage(frame,1.0,(500,500),[104,117,123],True,False)
    faceNet.setInput(blob)
    dets=faceNet.forward()
    res=[]
    for i in range(dets.shape[2]):
        conf=float(dets[0,0,i,2])
        if conf>0.4:
            x1=int(dets[0,0,i,3]*w); y1=int(dets[0,0,i,4]*h); x2=int(dets[0,0,i,5]*w); y2=int(dets[0,0,i,6]*h)
            x1,y1,x2,y2=max(0,x1),max(0,y1),min(w-1,x2),min(h-1,y2)
            face=orig[y1:y2,x1:x2]
            if face.size==0: continue
            gender,g_conf,age,a_conf,age_real=analyze(face, orig, (x1,y1,x2,y2))
            color=(212,175,55) if gender=='Female' else (123,184,255)
            cv2.rectangle(frame,(x1,y1),(x2,y2),color,3)
            label = "{} {}y".format(gender, age_real) if age_real>0 else "{}".format(gender)
            cv2.putText(frame,label,(x1,y1-10),cv2.FONT_HERSHEY_SIMPLEX,0.75,color,2,cv2.LINE_AA)
            res.append({"gender":gender,"gender_conf":round(float(g_conf),1),"age":age,"age_real":age_real,"age_conf":round(float(a_conf),1),"face_conf":round(conf*100,1),"box":[x1,y1,x2,y2]})
    return frame,res

